import json,pathlib,datetime
P=pathlib.Path('dist');cs=json.loads((P/'companies.json').read_text());m={x['ticker']:x['fundamental'] for x in json.loads((P/'analysis-audit.json').read_text())['metrics']};data={}
for c in cs:
 t=c['ticker'];f=c['analysis']['financial'];b=m[t]['balances'];dc=b['debtCurrent'];dn=b['debtNoncurrent'];cash=b['cash'];debt=dc['val']+dn['val'] if dc and dn and cash and cash['val']>0 and dc['end']==dn['end']==cash['end']==f['reportDate'] else None
 data[t]={'reportedDebtCash':debt/cash['val'] if debt is not None else None,'debtTags':[x['tag'] for x in [dc,dn] if x],'date':f['reportDate']}
(P/'scanner-data.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
ranking=json.loads((P/'ranking.json').read_text());historyfile=P/'ranking-history.json';history=json.loads(historyfile.read_text()) if historyfile.exists() else []
snapshot={'id':ranking['date']+'-method-v1','date':ranking['date'],'priceCutoff':ranking['priceCutoff'],'methodVersion':'Temel70 / Teknik30 v1','reason':'İlk kayıt: 101 şirket aynı temel ve teknik puanlama yöntemiyle sıralandı. Önceki tarihler için sonuç üretilmedi.','top10':ranking['ranking'][:10]}
if not any(x['id']==snapshot['id'] for x in history):history.append(snapshot)
(P/'ranking-history.json').write_text(json.dumps(history,ensure_ascii=False,indent=2))
