chain=[{'id':'chain-'+str(i),'name':name,'description':desc,'tickers':tickers.split()} for i,(name,desc,tickers) in enumerate(groups,1)];flat=[t for x in chain for t in x['tickers']];assert len(flat)==101 and len(set(flat))==101
